defense.vulnerable_config:
# mshta.exe not in AppLocker/WDAC deny list:
Get-AppLockerPolicy -Effective | Where-Object {$_.Rules | Select-String 'mshta'}
# No output → mshta.exe unrestricted

# Email gateway allows .hta attachments:
# Exchange: Get-TransportRule | Where-Object {$_.AttachmentExtensionMatchesWords -contains 'hta'}
# No transport rule blocking .hta = attachments delivered
